/* Ajour v0.7 — local synthetic-only role-based walkthrough. All clinical permissions enforced by Python API. */
const $=id=>document.getElementById(id);
const state={user:null,patients:[],scopes:{},patient:null,data:null,tab:'dashboard',metric:'glucose',period:'all',accounts:[],selectedEmail:null,preview:null,extra:{},catalog:null,specialty:null,domainFilter:'all',showOnlyMeasured:false,patientSearch:'',tabHistory:[]};
const ROLE={patient:'Particulier',family:'Proche aidant',doctor:'Médecin',pharmacist:'Pharmacien',nurse:'Infirmière',lab:'Laboratoire',optician:'Opticien',radiologist:'Radiologue',dentist:'Dentiste',podiatrist:'Podologue',orthotist:'Appareillage'};
const GLYPHS={patient:'♙',family:'♡',doctor:'✚',pharmacist:'✦',nurse:'✳',lab:'⌁',optician:'◉',radiologist:'◎',dentist:'✚',podiatrist:'◈',orthotist:'◈'};
const SCOPES={glucose:'Glycémie',vitals:'Tension et constantes',labs:'Bilans biologiques',meds:'Médicaments',messages:'Messagerie',tasks:'Consignes de soins',import:'Import de documents',vaccines:'Vaccins',prevention:'Prévention',appointments:'Rendez-vous',wellbeing:'Journal bien-être'};
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const date=s=>{if(!s)return 'Non renseignée';const d=new Date(s);return isNaN(d)?String(s).slice(0,10):d.toLocaleDateString('fr-FR',{day:'2-digit',month:'short',year:'numeric'});};
const clock=s=>{if(!s)return '';const d=new Date(s);return isNaN(d)?'':d.toLocaleString('fr-FR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});};
const localNow=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60*1000).toISOString().slice(0,16)};
const fmt=n=>Number(n).toLocaleString('fr-FR',{maximumFractionDigits:2});
const initials=s=>(s||'HB').split(' ').filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase();
const pid=()=>state.patient?.id;
const scope=s=>(state.scopes[pid()]||[]).includes('all')||(state.scopes[pid()]||[]).includes(s);
async function api(path,options={}){const req={credentials:'same-origin',...options,headers:{...(options.body && !(options.body instanceof FormData)?{'Content-Type':'application/json'}:{}),...(options.method && options.method!=='GET'?{'X-Healthberg-Action':'demo'}:{}),...(options.headers||{})}};const r=await fetch('/api'+path,req);const type=r.headers.get('content-type')||'';const body=type.includes('application/json')?await r.json():await r.text();if(!r.ok)throw Error(body?.detail||'Une erreur est survenue');return body}
const send=(path,data)=>api(path,{method:'POST',body:JSON.stringify(data)});
function toast(message,isError=false){const box=$('flash');box.textContent=message;box.classList.remove('hidden');box.classList.toggle('error',isError);setTimeout(()=>box.classList.add('hidden'),5000)}
async function start(){try{const me=await api('/auth/me');await acceptSession(me);}catch{await showLogin()}}
async function showLogin(){
 state.user=null;state.data=null;
 $('authScreen').classList.remove('hidden');$('appShell').classList.add('hidden');
 try{state.accounts=await api('/auth/accounts')}catch(err){$('loginError').textContent=err.message;return}
 const groups=[['Patients et proches',['patient','family']],['Cabinets et prescripteurs',['doctor','dentist']],['Examens et délivrance',['pharmacist','lab','radiologist','optician','podiatrist','orthotist','nurse']]];
 const used=new Set();
 const item=a=>{used.add(a.email);return `<button class="account-button ${state.selectedEmail===a.email?'selected':''}" data-account="${esc(a.email)}"><span class="account-ico">${GLYPHS[a.role]||'✚'}</span><span><b>${esc(a.role_name||ROLE[a.role]||a.role)}</b><small>${esc(a.name)}</small></span></button>`};
 $('accountList').innerHTML=groups.map(([label,roles])=>{const rows=roles.flatMap(role=>state.accounts.filter(a=>a.role===role&&!used.has(a.email)));return rows.length?`<div class="aj-account-heading">${esc(label)}</div>${rows.map(item).join('')}`:''}).join('')+state.accounts.filter(a=>!used.has(a.email)).map(item).join('');
 $('loginBtn').disabled=!state.selectedEmail;
}

async function doLogin(){if(!state.selectedEmail)return;try{await send('/auth/login',{email:state.selectedEmail,password:$('password').value});await acceptSession(await api('/auth/me'));}catch(err){$('loginError').textContent=err.message}}
async function acceptSession(payload){state.user=payload.user;state.tabHistory=[];state.patients=payload.patients;state.scopes=payload.scopes||{};state.patient=payload.patients[0]||null;state.tab=['optician','radiologist','dentist','podiatrist','orthotist'].includes(state.user.role)?'careflows':'dashboard';state.metric='glucose';state.extra={};state.domainFilter='all';state.patientSearch='';state.showOnlyMeasured=state.user.role!=='doctor';state.catalog=null;state.specialty=null;await loadMedicalCatalog();$('authScreen').classList.add('hidden');$('appShell').classList.remove('hidden');$('currentRole').textContent=`${ROLE[state.user.role]} · ${state.user.name}`;$('currentInitials').textContent=initials(state.user.name);nav();await refresh();}
async function logout(){try{await api('/auth/logout',{method:'POST'});}catch{}state.selectedEmail=null;state.tabHistory=[];await showLogin()}
function titles(){const role=state.user?.role||'patient';return {patient:'Ma santé',family:'Mes proches',doctor:'Mes patients',pharmacist:'Espace pharmacie',nurse:'Mes visites & soins',lab:'Résultats de laboratoire',optician:'Optique',radiologist:'Radiologie',dentist:'Cabinet dentaire',podiatrist:'Podologie',orthotist:'Orthèses & appareillage'}[role]}
function tabs(){const role=state.user.role;const s=state.scopes[pid()]||[];const has=x=>s.includes('all')||s.includes(x);const list=[['dashboard','▦',role==='patient'?'Aujourd’hui':'Vue d’ensemble']];
if(['patient','doctor','pharmacist','lab','family'].includes(role))list.push(['journeys','▣',role==='patient'?'Ordonnances & analyses':role==='doctor'?'Ordonnances & examens':role==='lab'?'Lire un QR laboratoire':role==='pharmacist'?'Scanner un QR':'Parcours']);
if(['patient','doctor','optician','radiologist','dentist','podiatrist','orthotist'].includes(role))list.push(['careflows','◎',role==='doctor'?'Imagerie & soins':role==='patient'?'Mes soins & images':'Demandes & imagerie']);
if(['patient','family','doctor','nurse'].includes(role)&&['glucose','vitals','labs'].some(has))list.push(['analyses','⌁',role==='doctor'?'Courbes du patient':'Mes courbes & analyses']);
if(['patient','family','doctor'].includes(role)&&['glucose','vitals','labs'].some(has))list.push(['story','▤',role==='doctor'?'Historique du patient':'Mon histoire']);
if(['patient','family','doctor','nurse'].includes(role)&&['glucose','vitals','labs'].some(has))list.push(['healthmap','▤',role==='doctor'?'Synthèse du patient':'Mes données']);
if(has('import')&&['patient','family','doctor'].includes(role))list.push(['documents','▤','Importer & sources']);
if(role==='patient')list.push(['profile','♙','Mon profil']);
if(has('meds'))list.push(['medications','◈','Traitements']);
if(has('vaccines')&&['patient','family','doctor'].includes(role))list.push(['vaccines','✹',role==='doctor'?'Vaccins du patient':'Mes vaccins']);
if(has('prevention')&&['patient','family','doctor'].includes(role))list.push(['prevention','◇',role==='doctor'?'Prévention du patient':'Ma prévention']);
if((role==='patient'||['doctor','dentist','nurse','optician','radiologist','podiatrist','orthotist'].includes(role)||has('appointments')))list.push(['appointments','▣','Rendez-vous']);
if(has('wellbeing')&&['patient','family'].includes(role))list.push(['wellbeing','♡','Mon bien-être']);
if(['patient','family'].includes(role))list.push(['professions','✚','Les spécialités']);
if(['lab','nurse','doctor','patient'].includes(role))list.push(['measure','＋',role==='lab'?'Saisie hors QR':role==='doctor'?'Saisir une mesure':'Ajouter une mesure']);
if(role==='nurse'||role==='doctor'||role==='patient')list.push(['notes','✎',role==='doctor'?'Notes du patient':'Notes de suivi']);
if(has('tasks'))list.push(['tasks','▣','Consignes de soins']);
if(has('messages'))list.push(['messages','✉','Messagerie']);
if(['patient','family','doctor','nurse','pharmacist'].includes(role))list.push(['team','↗','Partager & accès']);return list}

function nav(){
 const role=state.user.role, all=tabs(), patientLike=['patient','family'].includes(role);
 $('appShell').dataset.role=role;
 $('appShell').dataset.tab=state.tab;
 $('breadcrumb').textContent=state.tab==='dashboard'?titles():all.find(x=>x[0]===state.tab)?.[2]||titles();
 const trail=$('navTrail');if(trail)trail.innerHTML=['<button type="button" data-home>Accueil</button>',...state.tabHistory.slice(-3).map((key,i)=>`<button type="button" data-history-index="${state.tabHistory.length-Math.min(3,state.tabHistory.length)+i}">${esc(all.find(x=>x[0]===key)?.[2]||key)}</button>`)].join(' › ');
 const priorities={
   patient:['dashboard','story','journeys','team'],family:['dashboard','story','team'],
   doctor:['dashboard','journeys','healthmap','careflows','appointments'],
   pharmacist:['dashboard','journeys'],lab:['dashboard','journeys'],
   nurse:['dashboard','appointments','tasks','messages'],
   optician:['careflows','dashboard','appointments'],radiologist:['careflows','dashboard'],dentist:['careflows','dashboard'],podiatrist:['careflows','dashboard'],orthotist:['careflows','dashboard']
 };
 const main=all.filter(x=>(priorities[role]||['dashboard']).includes(x[0]));
 const more=all.filter(x=>!main.includes(x));
 const names={dashboard:role==='doctor'?'Dossier patient':role==='lab'?'Accueil laboratoire':role==='pharmacist'?'Accueil pharmacie':role==='nurse'?'Tournée & soins':role==='patient'?'Accueil':'Vue d’ensemble',journeys:role==='doctor'?'Ordonnances & examens':role==='pharmacist'?'Lire une ordonnance':role==='lab'?'Lire une demande':'Ordonnances & examens',healthmap:role==='doctor'?'Synthèse du patient': 'Mes données',careflows:role==='doctor'?'Imagerie & soins':'Imagerie & équipements',story:role==='doctor'?'Historique du patient':'Mon histoire',analyses:role==='doctor'?'Courbes du patient':'Mes courbes',vaccines:role==='doctor'?'Vaccins du patient':'Mes vaccins',prevention:role==='doctor'?'Prévention du patient':'Ma prévention',team:patientLike?'Partager mes données':'Accès au dossier',documents:role==='doctor'?'Documents du patient':'Mes documents',profile:'Mon profil'};
 const item=([key,icon,label])=>`<button data-tab="${key}" class="${state.tab===key?'active':''}" aria-current="${state.tab===key?'page':'false'}"><span class="ico" aria-hidden="true">${icon}</span>${esc(names[key]||label)}</button>`;
 $('nav').innerHTML=main.map(item).join('')+(more.length?`<details class="nav-more" ${more.some(x=>x[0]===state.tab)?'open':''}><summary>Autres fonctions <span aria-hidden="true">⌄</span></summary><div class="nav-more-body">${more.map(item).join('')}</div></details>`:'');
 const mobile=patientLike?['dashboard','story','journeys','team']:['dashboard','journeys','healthmap','careflows'];
 $('mobileNav').innerHTML=mobile.map(key=>{
  if(!all.some(x=>x[0]===key))return '';
  const labels={dashboard:'Accueil',story:'Histoire',journeys:role==='pharmacist'?'Scanner':role==='lab'?'Scanner':'Ordonnances',team:'Partager',healthmap:'Synthèse',careflows:'Soins'};
  const icons={dashboard:'⌂',story:'▤',journeys:'▣',team:'↗',healthmap:'⌁',careflows:'◎'};
  return `<button data-tab="${key}" class="${state.tab===key?'active':''}" aria-label="${labels[key]}" aria-current="${state.tab===key?'page':'false'}"><span aria-hidden="true">${icons[key]}</span><small>${labels[key]}</small></button>`;
 }).join('');
 const many=!['pharmacist','lab'].includes(role)&&(state.patients.length>1||['doctor','nurse'].includes(role));
 $('patientPickerWrap').classList.toggle('hidden',!many);
 const matches=state.patients.filter(p=>p.name.toLocaleLowerCase('fr').includes(state.patientSearch.toLocaleLowerCase('fr')));
 $('patientPicker').innerHTML=`${state.patients.length>4?`<label class="aj-patient-search-label" for="patientSearch">Rechercher un dossier</label><input id="patientSearch" class="aj-patient-search" type="search" autocomplete="off" placeholder="Nom du patient" value="${esc(state.patientSearch)}">`:''}<div class="aj-patient-list">${matches.map(p=>`<button class="patient-choice ${p.id===pid()?'active':''}" data-patient="${esc(p.id)}" aria-current="${p.id===pid()?'true':'false'}"><span class="tiny-avatar">${esc(p.initials)}</span><span><b>${esc(p.name)}</b><small>Identité fictive · À vérifier</small></span></button>`).join('')||'<p class="small">Aucun dossier autorisé correspondant.</p>'}</div>`;
}

async function refresh(){if(!pid()){state.data=null;await loadCareData();await practiceReload();render();return}try{state.data=await api(`/patients/${encodeURIComponent(pid())}/overview`);await loadExperience();await loadJourneyData();await loadCareData();await practiceReload();render();}catch(err){toast(err.message,true)}}
function hero(){
 const p=state.data?.patient||state.patient, role=state.user.role;
 const headings={doctor:'Mes patients',pharmacist:'Pharmacie',lab:'Laboratoire',nurse:'Mes soins',optician:'Optique',radiologist:'Radiologie',dentist:'Dentaire',podiatrist:'Podologie',orthotist:'Appareillage'};
 const clinical=role==='doctor'||role==='nurse'||['optician','radiologist','dentist','podiatrist','orthotist'].includes(role);
 const current=clinical&&p?`<div class="aj-current-patient"><span class="aj-current-avatar">${esc(p.initials||initials(p.name))}</span><span><strong>${esc(p.name)}</strong><small>Identité non qualifiée · ${esc(String(p.age??'—'))} ans · ${esc(p.identity?.profession||'Profession non renseignée')} · ID : ${esc(p.identity?.social_test_id||'non renseigné (test)')}</small></span><span class="aj-current-status">Dossier sélectionné</span></div>`:'';
 $('hero').innerHTML=`<div><div class="eyebrow">${esc((ROLE[role]||'Professionnel').toUpperCase())}</div><h1>${role==='patient'?'Bonjour, '+esc(state.user.name.split(' ')[0]):headings[role]||titles()}</h1>${current}</div><div class="hero-actions"><button class="btn outline" id="manualRefresh" aria-label="Actualiser les données">↻ Actualiser</button></div>`;
}

function ajNavigate(tab){if(!tabs().some(x=>x[0]===tab))return; if(state.tab!==tab){state.tabHistory.push(state.tab);state.tabHistory=state.tabHistory.slice(-12);}state.tab=tab;}
function ajHome(){state.tabHistory=[];state.tab='dashboard';refresh();$('sidebar').classList.remove('open')}
function ajBack(){const t=state.tabHistory.pop();if(!t)return ajHome();state.tab=t;refresh();}
function render(){nav();hero();const root=$('pageBody');if(!state.data && !['journeys','careflows'].includes(state.tab)){root.innerHTML='<div class="empty">Aucun dossier accessible à ce compte.</div>';return}const views={profile:ajProfilePage,dashboard:dashboard,journeys:journeysPage,careflows:carePage,healthmap:healthMapPage,analyses:analyses,story:storyPage,documents:documents,medications:medications,vaccines:vaccinesPage,prevention:preventionPage,appointments:appointmentsPage,wellbeing:wellbeingPage,professions:professionsPage,measure:measure,notes:notes,tasks:tasks,messages:messages,team:team};root.innerHTML=(views[state.tab]||dashboard)();if(state.tab==='team'&&state.user.role==='patient')loadGrants();if(state.tab==='dashboard'&&state.user.role==='lab')loadLabResults();}
function panel(title,body,subtitle='',headerExtra=''){return `<section class="panel"><div class="panel-header"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${headerExtra}</div>${body}</section>`}
function row(label,detail,end='',symbol='◉'){return `<div class="row-item"><span class="row-symbol">${symbol}</span><span class="row-info"><strong>${esc(label)}</strong><small>${esc(detail)}</small></span><span class="row-end">${end}</span></div>`}
function selectMetrics(id){return `<select class="select" id="${id}">${(state.data.metrics||[]).map(m=>`<option value="${esc(m.code)}" ${state.metric===m.code?'selected':''}>${esc(m.label)}</option>`).join('')}</select>`}
function accessibleMetric(code){return (state.data.metrics||[]).some(m=>m.code===code)}
function metricDefault(){if(!accessibleMetric(state.metric))state.metric=(state.data.metrics||[])[0]?.code||'';return state.metric}
function latestValues(){const last=state.data.last_values||{};let order=['glucose','systolic','hba1c','pulse','creatinine','weight'];return order.filter(c=>last[c]).slice(0,4).map(c=>{const o=last[c];const codeName=state.data.metrics.find(m=>m.code===c)?.label||c;return `<article class="kpi"><div class="kpi-top"><span>${esc(codeName)}</span><span class="kpi-icon">${c==='glucose'?'◉':c==='systolic'?'♡':'⌁'}</span></div><div class="kpi-value">${fmt(o.value)} <small>${esc(o.unit)}</small></div><div class="kpi-foot">${date(o.measured_at)} · ${esc(o.status==='synthetic_verified'?'Simulation':o.status==='professional_verified'?'Saisie pro':'Déclaré')}</div></article>`}).join('')}
function patientHome(){
 const care=(careState.orders||[]),rx=(journeyState.orders||[]),newest=[...(state.data?.observations||[]),...(state.data?.findings||[])].sort((a,b)=>b.measured_at.localeCompare(a.measured_at))[0];
 const categories=[['Médicaments',rx.filter(x=>x.kind==='prescription').length],['Analyses',rx.filter(x=>x.kind==='lab').length],['Optique',care.filter(x=>x.kind==='optical').length],['Imagerie',care.filter(x=>x.kind==='imaging').length],['Dentaire',care.filter(x=>x.kind==='dental').length],['Autres soins',care.filter(x=>!['optical','imaging','dental'].includes(x.kind)).length]];
 return `<div class="aj-practice-stack">${practiceAppointmentCard()}
 <section class="aj-practice-strip"><div class="aj-section-heading"><h3>Votre dossier</h3></div>
 ${practiceBtn('Mon histoire médicale','story','▤')}
 ${practiceBtn('Mes ordonnances','orders','▣')}
 <div class="aj-practice-tags">${categories.map(([label,count])=>`<span>${esc(label)}${count?` <b>${count}</b>`:''}</span>`).join('')}</div>
 ${newest?`<button class="aj-news" data-tab="analyses"><span class="aj-news-icon">⌁</span><span><b>Dernier résultat : ${esc(newest.label)}</b><small>${esc(date(newest.measured_at))} · Voir son origine</small></span><span>›</span></button>`:`<div class="aj-muted-detail">Vos résultats apparaîtront ici lorsqu'un document sera ajouté.</div>`}
 </section>
 <section class="aj-practice-strip"><h3>Accès rapide</h3><div class="aj-practice-quick">${['Mon profil','Mes documents','Mes traitements','Mes vaccins','Ma prévention','Mon bien-être'].map((name,i)=>`<button data-tab="${['profile','documents','medications','vaccines','prevention','wellbeing'][i]}">${name}<span>›</span></button>`).join('')}</div></section>
 </div>`;
}
function ajClinicalAction(title,sub,tab,icon,anchor=''){
 return `<button class="aj-work-action" ${anchor?`data-jump="${tab}:${anchor}"`:`data-tab="${tab}"`}><span class="aj-work-icon" aria-hidden="true">${icon}</span><span><strong>${esc(title)}</strong><small>${esc(sub)}</small></span><span class="aj-work-chevron" aria-hidden="true">›</span></button>`;
}
function ajDoctorWorkspace(){
 const p=state.data?.patient||state.patient;
 if(!p)return panel('Aucun dossier sélectionné','<p>Choisissez un patient autorisé pour consulter son dossier.</p>');
 const all=journeyState.orders||[], outcomes=journeyState.outcomes||[], last=state.data?.last_values||{}, events=state.data?.events||[];
 const active=all.filter(o=>o.status==='issued');
 const resultFlags=outcomes.slice(0,5);
 const measurements=['glucose','systolic','hba1c','creatinine'].filter(k=>last[k]).slice(0,3);
 const recordRows=measurements.map(k=>{const x=last[k], name=state.data.metrics?.find(m=>m.code===k)?.label||k;return `<div class="aj-work-record"><span><b>${esc(name)}</b><small>${date(x.measured_at)}</small></span><strong>${fmt(x.value)} <small>${esc(x.unit)}</small></strong></div>`}).join('');
 const list=active.slice(0,4).map(o=>`<div class="aj-work-record"><span><b>${esc(o.label)}</b><small>${o.kind==='lab'?'Biologie':'Prescription'} · ${date(o.issued_at)}</small></span><span class="aj-work-label">En cours</span></div>`).join('');
 return `<div class="aj-workspace"><div class="aj-work-header"><div><span class="aj-work-eyebrow">DOSSIER DE ${esc(p.name.toUpperCase())}</span><h2>Que souhaitez-vous faire ?</h2></div><span class="aj-work-identity">Identité fictive : non qualifiée</span></div>
 <div class="aj-work-actions">${ajClinicalAction('Importer une ordonnance','PDF du logiciel habituel','journeys','▤','ajImportSection')}${ajClinicalAction('Demander des analyses','Créer une demande de biologie','journeys','⌁','ajLabSection')}${ajClinicalAction('Voir les résultats','Valeurs, dates et provenance','analyses','◉')}${ajClinicalAction('Imagerie & soins','Examens, radios et comptes rendus','careflows','◎')}</div>
 <div class="aj-work-grids"><section class="aj-work-panel"><div class="aj-work-panel-head"><h3>Derniers résultats</h3><button data-tab="journeys">Voir les détails</button></div>${resultFlags.length?resultFlags.map(r=>`<div class="aj-work-record"><span><b>${esc(state.data.metrics?.find(m=>m.code===r.code)?.label||r.code)}</b><small>${date(r.measured_at)} · Laboratoire</small></span><span>${ajFlag(r.lab_flag)}</span></div>`).join(''):'<p class="aj-work-empty">Aucun résultat de laboratoire publié.</p>'}<p class="aj-work-fine">Statuts transmis par le laboratoire, sans diagnostic automatisé.</p></section>
 <section class="aj-work-panel"><div class="aj-work-panel-head"><h3>Demandes à suivre</h3><button data-tab="journeys">Ouvrir</button></div>${list||'<p class="aj-work-empty">Aucune demande active.</p>'}<div class="aj-work-panel-head aj-work-subhead"><h3>Repères récents</h3><button data-tab="healthmap">Synthèse</button></div>${recordRows||'<p class="aj-work-empty">Aucune mesure renseignée.</p>'}</section></div>
 <div class="aj-work-foot"><button data-tab="healthmap">Synthèse par spécialité</button><button data-tab="appointments">Rendez-vous</button><button data-tab="notes">Notes de suivi</button><button data-tab="documents">Documents et sources</button></div></div>`;
}
function ajPharmacyWorkspace(){return `<div class="aj-workspace aj-provider-workspace"><div class="aj-work-header"><div><span class="aj-work-eyebrow">ACCUEIL PHARMACIE</span><h2>Lire une ordonnance</h2></div></div><div class="aj-provider-lead"><span class="aj-provider-lead-icon">▣</span><div><h3>Le patient présente son QR Ajour</h3><p>Scannez-le ou saisissez son code. Seule l’ordonnance partagée sera consultable.</p><button class="btn primary" data-tab="journeys">Scanner le QR</button></div></div><div class="aj-provider-info"><strong>Après la lecture</strong><span>Contrôler les lignes · Exporter le PDF · Consigner la délivrance</span></div><p class="aj-work-fine">Ajour ne réalise aucune facturation ni télétransmission à l’Assurance maladie.</p></div>`;}
function ajLabWorkspace(){return `<div class="aj-workspace aj-provider-workspace"><div class="aj-work-header"><div><span class="aj-work-eyebrow">ACCUEIL LABORATOIRE</span><h2>Recevoir une demande</h2></div></div><div class="aj-provider-lead"><span class="aj-provider-lead-icon">⌁</span><div><h3>Lire le QR de la demande</h3><p>Vérifiez les examens demandés, puis publiez les valeurs et les statuts transmis par le laboratoire.</p><button class="btn primary" data-tab="journeys">Lire le QR</button></div></div><div class="aj-provider-info"><strong>Après la lecture</strong><span>Examens → résultats → dossier patient et médecin autorisé</span></div><div class="aj-work-foot"><button data-jump="journeys:ajLabSlotsSection">Gérer les rendez-vous</button><button data-tab="measure">Saisie de démonstration hors QR</button></div></div>`;}
function ajNurseWorkspace(){return `<div class="aj-workspace"><div class="aj-work-header"><div><span class="aj-work-eyebrow">SOINS</span><h2>Mes actions</h2></div></div><div class="aj-work-actions">${ajClinicalAction('Consignes de soins','Soins prévus et réalisés','tasks','▣')}${ajClinicalAction('Transmettre une observation','Note datée dans le dossier','notes','✎')}${ajClinicalAction('Ajouter une mesure','Constantes et suivi','measure','⌁')}${ajClinicalAction('Messages','Échanges autorisés','messages','✉')}</div></div>`;}
function dashboard(){if(state.user.role==='patient')return patientHome();if(state.user.role==='doctor')return ajDoctorWorkspace();if(state.user.role==='lab')return ajLabWorkspace();if(state.user.role==='pharmacist')return ajPharmacyWorkspace();if(state.user.role==='nurse')return ajNurseWorkspace();const obs=state.data.observations||[], meds=state.data.medications||[],latest=obs.slice(-5).reverse(),events=(state.data.events||[]).slice(0,6);metricDefault();const kpis=latestValues();return `${state.user.role==='patient'?storyIntro():state.user.role==='doctor'?doctorSpecialtyIntro()+ajResultCards():''}<div class="grid-kpis">${kpis||'<div class="empty">Aucune mesure visible pour ce profil.</div>'}</div><div class="dashboard-cols"><div class="column">${panel(state.user.role==='patient'?'Mes courbes dans le temps':'Courbes du patient',`<div class="panel-header"><span class="small">Chaque point conserve sa source et sa date.</span><div class="inline-actions">${selectMetrics('metricChooser')}<select id="periodChooser" class="select"><option value="all" ${state.period==='all'?'selected':''}>Toutes dates</option><option value="12" ${state.period==='12'?'selected':''}>12 derniers mois</option><option value="6" ${state.period==='6'?'selected':''}>6 mois</option></select></div></div><div id="graph" class="chart-container">${drawChart(state.metric)}</div><div class="chart-caption"><span>Lecture et visualisation, sans diagnostic automatisé.</span><span>Cliquer sur un point pour voir sa source.</span></div>`)}${panel('Dernières mesures',latest.length?latest.map(o=>row(o.label,date(o.measured_at)+' · '+o.status,`${fmt(o.value)} <small>${esc(o.unit)}</small>`,'⌁')).join(''):'<div class="empty">Aucune mesure accessible</div>')}</div><div class="column">${panel(state.user.role==='patient'?'Mon parcours récent':'Parcours du patient',events.length?events.map(e=>row(e.description,clock(e.created_at),'',e.kind==='measurement'?'⌁':e.kind==='message'?'✉':'◎')).join(''):'<div class="empty">Les nouveaux résultats apparaîtront ici.</div>','Événements actualisés depuis les autres comptes')}${scope('meds')?panel(state.user.role==='patient'?'Mes médicaments':'Médicaments du patient',meds.slice(0,4).map(m=>row(m.name,m.schedule,`<small>${esc(m.state==='professional_verified'?'Prescription de démo':'Historique / déclaré')}</small>`,'◈')).join('')||'<div class="empty">Aucun traitement déclaré</div>','Prescrit ≠ délivré ≠ pris'):''}${scope('tasks')?panel('Soins & rendez-vous',taskItems(state.data.tasks||[]).slice(0,2).join('')||'<div class="empty">Aucune consigne en cours.</div>'):''}</div></div>`}
function drawChart(code){const obs=(state.data?.observations||[]).filter(o=>o.code===code).sort((a,b)=>a.measured_at.localeCompare(b.measured_at));if(!obs.length)return '<div class="empty">Aucune donnée pour cette courbe. Ajoutez un résultat fictif pour commencer.</div>';const cutoff=state.period==='all'?0:Date.now()-Number(state.period)*31*86400000;const data=obs.filter(o=>new Date(o.measured_at).getTime()>=cutoff).slice(-100);if(!data.length)return '<div class="empty">Pas de données sur cette période.</div>';let vals=data.map(x=>+x.value);let min=Math.min(...vals),max=Math.max(...vals);let pad=Math.max((max-min)*.18,.5);if(max===min)pad=Math.max(Math.abs(max)*.15,.5);min-=pad;max+=pad;const X=i=>data.length===1?320:56+i/(data.length-1)*570;const Y=v=>195-(v-min)/(max-min)*158;const pts=data.map((d,i)=>`${X(i)},${Y(+d.value)}`).join(' ');const label=state.data.metrics.find(m=>m.code===code);const grid=[0,1,2,3,4].map(i=>{const y=36+i*39.5;const v=max-(max-min)*(i/4);return `<line class="chart-grid" x1="54" y1="${y}" x2="641" y2="${y}"/><text class="chart-tick" x="8" y="${y+3}">${fmt(v)}</text>`}).join('');const dots=data.map((d,i)=>`<circle class="chart-point" data-source="${esc(d.source_id)}" data-value="${esc(d.value)}" data-code="${esc(code)}" data-date="${esc(d.measured_at)}" cx="${X(i)}" cy="${Y(+d.value)}" r="4.4"><title>${esc(date(d.measured_at))} · ${esc(d.value)} ${esc(d.unit)}</title></circle>`).join('');const first=date(data[0].measured_at),last=date(data[data.length-1].measured_at);return `<svg viewBox="0 0 670 235" role="img" aria-label="Évolution de ${esc(label?.label||code)} sur ${data.length} mesures"><defs><linearGradient id="hbfade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#32cbb6" stop-opacity=".18"/><stop offset="1" stop-color="#32cbb6" stop-opacity="0"/></linearGradient></defs>${grid}<polygon fill="url(#hbfade)" points="${X(0)},206 ${pts} ${X(data.length-1)},206"/><polyline class="chart-line" points="${pts}"/>${dots}<text class="chart-tick" x="57" y="227">${esc(first)}</text><text class="chart-tick" x="640" text-anchor="end" y="227">${esc(last)}</text></svg><div class="small">${data.length} valeur(s) · ${esc(label?.unit||'')} · aucune extrapolation</div>`}
function analyses(){metricDefault();const obs=(state.data.observations||[]).filter(o=>o.code===state.metric).sort((a,b)=>b.measured_at.localeCompare(a.measured_at));return `<div class="stack">${panel('Explorer mes analyses',`<div class="panel-header">${selectMetrics('analysisMetricChooser')}<select id="periodChooser" class="select"><option value="all" ${state.period==='all'?'selected':''}>Toutes dates</option><option value="12" ${state.period==='12'?'selected':''}>12 mois</option><option value="6" ${state.period==='6'?'selected':''}>6 mois</option></select></div><div id="graph" class="chart-container">${drawChart(state.metric)}</div>`,'Valeurs documentées dans leur historique, sans interprétation clinique')}${ajFindingsPanel()}${ajDocumentPagesPanel()}${panel('Toutes les valeurs',`<div class="table-scroll"><table class="table"><thead><tr><th>Date</th><th>Paramètre</th><th>Valeur</th><th>Origine</th></tr></thead><tbody>${obs.map(o=>`<tr><td>${date(o.measured_at)}</td><td>${esc(o.label)}</td><td><b>${fmt(o.value)} ${esc(o.unit)}</b></td><td><button class="pill-button" data-source="${esc(o.source_id)}">Voir provenance ↗</button></td></tr>`).join('')||'<tr><td colspan="4">Aucun résultat</td></tr>'}</tbody></table></div>`)}</div>`}
function ajProfilePage(){const p=state.data?.patient||{};const x=p.identity||{};if(state.user.role!=='patient')return panel('Identité','Accès non autorisé');return panel('Mon profil et mes coordonnées',`<p class="small">Renseignez les informations de votre profil. Leur présence ne constitue pas une vérification d’identité.</p><form id="patientIdentityForm" class="simple-form"><label>Nom du dossier<input value="${esc(p.name||'')}" readonly></label><label>Date de naissance<input name="birth_date" type="date" value="${esc(x.birth_date||'')}"></label><label>Adresse de test<input name="address" maxlength="160" placeholder="Ex. 10 rue des Démonstrations" value="${esc(x.address||'')}"></label><label>Profession<input name="profession" maxlength="160" placeholder="Ex. Enseignante" value="${esc(x.profession||'')}"></label><label>Organisme complémentaire (test)<input name="insurer" maxlength="160" placeholder="Ex. Mutuelle Démo" value="${esc(x.insurer||'')}"></label><label>N° d’adhérent TEST<input name="member_test_id" maxlength="160" placeholder="TEST-ADHERENT-001" value="${esc(x.member_test_id||'')}"></label><label>Référence assurance de validation<input name="social_test_id" maxlength="160" placeholder="TEST-PATIENT-001" value="${esc(x.social_test_id||'')}"></label><button class="btn primary">Enregistrer mes informations de test</button></form>`, 'Dans la version clinique, ce parcours devra utiliser une identification INS qualifiée et des contrôles adaptés.');}
function documents(){const receipts=state.data.receipts||[];return `<div class="stack">${panel('Faire parler mes anciens documents',`<div class="upload-box"><div style="font-size:32px;color:#159b88">▤</div><h3>Importer une analyse ou une ordonnance fictive</h3><p class="small">PDF, photo ou scan → lecture → vérification → intégration dans vos courbes. Le fichier original n’est pas conservé.</p><button class="btn primary" id="openImport">＋ Importer un fichier</button></div><div class="warning-box" style="margin-top:17px">Utilisez uniquement des documents fictifs. Aucune donnée médicale réelle, y compris celle de votre famille, ne doit être envoyée dans ce prototype.</div>`)}${ajFindingsPanel()}${ajDocumentPagesPanel()}${panel('Historique des sources',receipts.length?`<div class="table-scroll"><table class="table"><thead><tr><th>Type</th><th>Source</th><th>Date</th><th>Traçabilité</th></tr></thead><tbody>${receipts.map(r=>`<tr><td>${esc(r.document_kind)}</td><td>${esc(r.issuer||'Non identifié')}</td><td>${date(r.document_date||r.imported_at)}</td><td><button class="pill-button" data-source="${esc(r.id)}">Reçu de source ↗</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Les sources apparaîtront après import.</div>','Chaque résultat conserve une empreinte et une fiche documentaire, pas le PDF original.')}</div>`}
function renderMedsRows(meds){return meds.map(m=>`<div class="row-item"><span class="row-symbol">◈</span><span class="row-info"><strong>${esc(m.name)}</strong><small>${esc(m.schedule)} · ${esc(m.state==='professional_verified'?'Prescription structurée fictive':'Historique ou déclaration')}</small>${(m.dispenses||[]).map(d=>`<small>Délivré (fictif) : ${esc(d.quantity)}, ${date(d.created_at)}</small>`).join('')}</span>${state.user.role==='pharmacist'?`<button class="pill-button" data-tab="journeys">Lire le QR patient</button>`:''}</div>`).join('')||'<div class="empty">Aucun traitement visible.</div>'}
function medications(){const meds=state.data.medications||[];return `<div class="stack">${panel('Prescrit, délivré, pris : trois réalités différentes',renderMedsRows(meds),'La présence d’un traitement historique ne signifie pas qu’il est actuellement prescrit.')}${state.user.role==='doctor'?panel('Créer une ordonnance et son QR code',`<p>Prescrivez depuis le parcours connecté pour que le patient puisse présenter un QR à la pharmacie.</p><button class="btn primary" data-tab="journeys">Créer une ordonnance</button>`):''}${state.user.role==='pharmacist'?'<div class="warning-box">Vous ne voyez que les médicaments et leurs dosages pour ce patient. Les analyses biologiques et les notes psychosociales ne sont pas exposées dans ce profil de démonstration.</div>':''}</div>`}
function genericMeasureForm(){const metrics=state.user.role==='lab'?state.data.metrics:state.data.metrics;return `<form id="measureForm" class="form-grid"><div class="form-field"><label>Paramètre</label><select name="code" id="measureCode" class="select" required>${metrics.map(m=>`<option value="${esc(m.code)}" data-unit="${esc(m.unit)}">${esc(m.label)} · ${esc(m.unit)}</option>`).join('')}</select></div><div class="form-field"><label>Valeur fictive</label><input type="number" name="value" step="any" required placeholder="Ex. 1.18"></div><div class="form-field"><label>Unité</label><input id="measureUnit" name="unit" value="${esc(metrics[0]?.unit||'')}" required></div><div class="form-field"><label>Date et heure de la mesure</label><input type="datetime-local" name="measured_at" value="${localNow()}" required></div><div class="form-field full"><label>Contexte (facultatif)</label><input name="context" maxlength="160" placeholder="Ex. à jeun / prise à domicile / bilan laboratoire fictif"></div><div class="form-field full"><button type="submit" class="btn primary">${state.user.role==='lab'?'Publier le résultat laboratoire':'Enregistrer cette mesure'} →</button></div></form>`}
function measure(){return `<div class="dashboard-cols"><div class="column">${panel(state.user.role==='lab'?'Résultat de biologie fictif':'Nouvelle mesure fictive',genericMeasureForm(),'Les données seront visibles dans les comptes autorisés au prochain rafraîchissement.')}</div><div class="column">${panel('Transmission synchronisée',`<div class="stack">${row('1. Saisir',"Choisir le paramètre, l’unité, la valeur et la date",'','✎')}${row('2. Enregistrer','Le serveur vérifie le rôle et le dossier','', '◈')}${row('3. Consulter','Les courbes autorisées se mettent à jour','', '⌁')}</div>`)}<div class="warning-box">Aucune valeur ne déclenche d’alerte ni de décision médicale. Ceci n’est pas un système de télésurveillance.</div></div></div>`}
function notes(){const rows=state.data.notes||[];return `<div class="dashboard-cols"><div class="column">${panel('Notes de suivi de l’équipe soignante',rows.length?rows.map(n=>row(n.kind==='psychosocial'?'Observation psychosociale':n.kind==='treatment_concern'?'Question sur un traitement':'Compte rendu de visite',n.author+' · '+clock(n.created_at),`<small>${esc(n.body)}</small>`,'✎')).join(''):'<div class="empty">Aucune note autorisée</div>','Ces notes ne sont jamais automatiquement partagées avec les proches.')}</div><div class="column">${state.user.role==='nurse'?panel('Rédiger une note de visite',`<form id="noteForm" class="stack"><div class="form-field"><label>Nature de la note</label><select name="kind" class="select"><option value="visit">Observations de visite</option><option value="psychosocial">Aspect psychologique / ressenti</option><option value="treatment_concern">Souhait d’arrêt ou question sur un traitement</option></select></div><div class="form-field"><label>Observation fictive</label><textarea name="body" minlength="2" maxlength="1500" required placeholder="Ex. la personne évoque des inquiétudes au sujet de son traitement..."></textarea></div><button class="btn primary" type="submit">Enregistrer et rendre visible au médecin</button></form>`):panel('Informations sensibles',`<div class="warning-box">Les notes de suivi psychosocial sont visibles uniquement au patient, au médecin autorisé et à leur auteur dans cette simulation. Pas de partage familial automatique.</div>`)}</div></div>`}
function taskItems(tasks){return tasks.map(t=>`<div class="row-item"><span class="row-symbol">▣</span><span class="row-info"><strong>${esc(t.title)}</strong><small>${esc(t.assignee)} · prévu le ${date(t.due_date)}</small></span><span class="row-end"><span class="tag ${t.status==='done'?'':'gold'}">${t.status==='done'?'Terminé':'À faire'}</span>${state.user.role==='nurse'&&t.status!=='done'?`<br><button class="pill-button" style="margin-top:9px" data-complete="${esc(t.id)}">Marquer fait</button>`:''}</span></div>`)}
function tasks(){const tasks=state.data.tasks||[];const nurse=(state.data.contacts||[]).filter(x=>x.role==='nurse');return `<div class="dashboard-cols"><div class="column">${panel('Programme de soins',taskItems(tasks).join('')||'<div class="empty">Aucune consigne planifiée</div>','Chaque tâche a un auteur, un destinataire et une date.')}</div><div class="column">${state.user.role==='doctor'?panel('Créer une consigne fictive',`<form id="taskForm" class="stack"><div class="form-field"><label>Infirmière destinataire</label><select name="assignee_id" class="select" required>${nurse.map(n=>`<option value="${esc(n.id)}">${esc(n.name)}</option>`).join('')}</select></div><div class="form-field"><label>Consigne</label><input name="title" required maxlength="150" placeholder="Ex. Prendre la tension à domicile"></div><div class="form-field"><label>Date prévue</label><input name="due_date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><button class="btn primary">Envoyer la consigne</button></form>`):panel('Coordination',`<div class="small">Les consignes et les états « à faire » ou « fait » sont partagés avec les personnes autorisées.</div>`)}</div></div>`}
function messages(){const m=state.data.messages||[],contacts=(state.data.contacts||[]).filter(x=>x.id!==state.user.id&&x.role!=='lab');return `<div class="dashboard-cols"><div class="column">${panel('Mes échanges',m.length?`<div class="messages">${m.map(x=>`<div class="message ${x.sender_id===state.user.id?'mine':''}"><b>${esc(x.author)} → ${esc(x.recipient)} <time>${clock(x.created_at)}</time></b><p>${esc(x.body)}</p></div>`).join('')}</div>`:'<div class="empty">Votre messagerie est vide.</div>','Échanges internes fictifs, non urgents. Aucun triage médical automatisé.')}</div><div class="column">${panel('Écrire à un professionnel ou un proche',`<form id="messageForm" class="stack"><div class="form-field"><label>Destinataire autorisé</label><select name="recipient_id" class="select" required>${contacts.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(ROLE[p.role])}</option>`).join('')}</select></div><div class="form-field"><label>Votre message</label><textarea name="body" required minlength="2" maxlength="1400" placeholder="Ex. question fictive sur le traitement ou sur la prochaine visite..."></textarea></div><button class="btn primary" ${!contacts.length?'disabled':''} type="submit">Envoyer le message</button></form>`, 'Le destinataire consultera le message depuis son espace.')}</div></div>`}
function team(){const members=(state.data.contacts||[]).filter(x=>x.id!==state.user.id);const list=members.length?`<div class="team-cards">${members.map(m=>`<div class="team-card"><span class="member-avatar">${esc(initials(m.name))}</span><div><b>${esc(m.name)}</b><small>${esc(ROLE[m.role]||m.role)} · compte de démonstration</small></div></div>`).join('')}</div>`:'<div class="empty">Aucun contact visible pour ce rôle.</div>';return `<div class="stack">${panel('Les personnes qui participent au suivi',list,'Chaque personne a un rôle et des autorisations spécifiques.')}${state.user.role==='patient'?panel('Je décide qui peut accéder à mon dossier',`<div id="familyGrants" class="small">Chargement des autorisations…</div>`,'Les accès des professionnels sont simulés et doivent être accordés explicitement dans cette démonstration.'):'<div class="warning-box">Dans cette version, les habilitations sont simulées côté serveur. Elles ne remplacent pas la vérification d’identité professionnelle et le consentement nécessaires en situation réelle.</div>'}${state.user.role==='patient'?panel('Mon journal des consultations',`<div id="auditLog" class="small">Chargement du journal…</div>`):''}</div>`}
async function loadGrants(){try{const [g,a,all]=await Promise.all([api(`/patients/${pid()}/grants`),api(`/patients/${pid()}/audit`),api('/demo/directory')]);const known=new Set(g.grants.map(x=>x.user_id));const choice=all.filter(x=>!known.has(x.id));$('familyGrants').innerHTML=g.grants.map(x=>`<form data-grant="${esc(x.user_id)}" class="stack" style="border:1px solid #e5edf3;border-radius:12px;padding:16px;margin-bottom:12px"><b>${esc(x.name)} · ${esc(ROLE[x.role])}</b>${x.role==='family'?`<div class="permissions">${g.allowed_permissions.map(p=>`<label class="perm"><input type="checkbox" name="permission" value="${p}" ${x.permissions.includes(p)?'checked':''}>${esc(SCOPES[p]||p)}</label>`).join('')}</div>`:`<p class="small">Droits professionnels prédéfinis pour le rôle ${esc(ROLE[x.role])}. Aucun choix libre de données sensibles pour ce compte.</p>`}<label class="perm"><input type="checkbox" name="revoked" ${x.revoked?'checked':''}>Suspendre cet accès</label><div><button class="btn secondary" type="submit">Enregistrer les accès</button></div></form>`).join('')+`<div style="border:1px dashed #c8dedb;padding:17px;border-radius:12px"><h3 style="margin-top:0">Inviter un compte de démonstration</h3><form id="inviteForm" class="stack"><div class="form-field"><label>Compte disponible</label><select class="select" name="user_id" required>${choice.map(u=>`<option value="${esc(u.id)}">${esc(u.name)} · ${esc(ROLE[u.role])}</option>`).join('')}</select></div><p class="small">Proche : glycémie, tension, médicaments et messages par défaut. Professionnel : droits prédéfinis selon son métier.</p><button class="btn primary" type="submit" ${choice.length?'':'disabled'}>Accorder l’accès au dossier fictif</button></form></div>`;$('auditLog').innerHTML=a.slice(0,12).map(x=>row(x.action,clock(x.at)+' · '+(x.actor||'Utilisateur fictif'),'','◌')).join('')||'Aucune activité enregistrée';}catch(err){toast(err.message,true)}}
async function loadLabResults(){if(state.user.role!=='lab')return;try{const l=await api(`/patients/${pid()}/lab-submissions`);const target=$('labResults');if(target)target.innerHTML=l.length?l.map(o=>row(o.label,date(o.measured_at),`${fmt(o.value)} ${esc(o.unit)}`,'⌁')).join(''):'<div class="empty">Aucun résultat publié depuis ce compte.</div>'}catch(err){toast(err.message,true)}}
function showModal(html){$('modalContent').innerHTML=html;$('modal').classList.remove('hidden')}
function closeModal(){$('modal').classList.add('hidden');state.preview=null}
async function showSource(rid){try{const r=await api(`/patients/${pid()}/receipts/${encodeURIComponent(rid)}`);showModal(`<div class="eyebrow">FICHE DE PROVENANCE</div><h2>${esc(r.document_kind)}</h2><p class="small">Les documents originaux ne sont pas conservés. Cette fiche ne certifie pas l’authenticité d’un fichier supprimé.</p><div class="table-scroll"><table class="table"><tbody><tr><th>Émetteur</th><td>${esc(r.issuer||'Non identifié')}</td></tr><tr><th>Date source</th><td>${date(r.document_date)}</td></tr><tr><th>Import</th><td>${clock(r.imported_at)}</td></tr><tr><th>Méthode</th><td>${esc(r.extraction_method)}</td></tr><tr><th>Pages</th><td>${esc(r.page_count)}</td></tr><tr><th>SHA-256</th><td style="overflow-wrap:anywhere">${esc(r.sha256)}</td></tr><tr><th>Original stocké</th><td><b>Non</b></td></tr></tbody></table></div><div class="warning-box">Empreinte et source déclarée ≠ validation clinique. Si le document est contesté, son original devra être redemandé.</div>`)}catch(err){toast(err.message,true)}}
function showRegister(){showModal(`<div class="eyebrow">NOUVELLE IDENTITÉ FICTIVE</div><h2>Créer un compte Ajour</h2><p class="small">Créez un autre profil pour simuler des interactions. N’utilisez aucun nom, email ou dossier médical réel. Un professionnel créé ici n’a accès à aucun patient tant qu’un patient fictif ne lui a pas accordé l’accès.</p><form id="registerForm" class="stack"><div class="form-field"><label>Profil</label><select name="role" id="registerRole" class="select"><option value="patient">Particulier</option><option value="family">Proche aidant</option><option value="doctor">Médecin</option><option value="pharmacist">Pharmacien</option><option value="nurse">Infirmière</option><option value="lab">Laboratoire</option></select></div><div class="form-field"><label>Nom fictif</label><input name="name" required maxlength="70" minlength="3" placeholder="Ex. Dr Camille Démo"></div><div id="registerPatientFields" class="aj-profile-fields"><label>Date de naissance fictive<input type="date" name="birth_date"></label><label>Adresse fictive<input name="address" maxlength="160" placeholder="10 rue du Test"></label><label>Profession<input name="profession" maxlength="160"></label><label>Mutuelle fictive<input name="insurer" maxlength="160"></label><label>N° adhérent fictif<input name="member_test_id" placeholder="TEST-ADHERENT-001" maxlength="160"></label><label>Identifiant d’assurance TEST (pas un NIR)<input name="social_test_id" placeholder="TEST-PATIENT-001" maxlength="160"></label></div><button class="btn primary" type="submit">Créer ce compte</button></form>`)}
function showImport(){showModal(`<div class="eyebrow">MOTEUR D’HISTORIQUE · DÉMO</div><h2>Importer un document</h2><p class="small">Importez un PDF, une photo ou un scan. Ajour extrait les paramètres reconnus et vous demande de les vérifier avant de les enregistrer.</p><form id="uploadForm" class="stack"><div class="upload-box"><div style="font-size:30px;color:#168d83">▤</div><input type="file" id="docFile" name="file" accept=".pdf,.jpg,.jpeg,.png" required></div><button class="btn primary" type="submit">Analyser le document</button></form><div id="previewSpace"></div>`)}
function ajManualLine(){const metrics=state.data?.metrics||[],commonDay=$('ajImportDate')?.value;return `<div class="aj-manual-line"><label>Paramètre<select class="select" data-manual-code>${metrics.map(m=>`<option value="${esc(m.code)}" data-unit="${esc(m.unit)}">${esc(m.label)}</option>`).join('')}</select></label><label>Valeur lue dans le document<input type="number" step="any" data-manual-value placeholder="Ex. 1.18" required></label><label>Unité<input data-manual-unit readonly value="${esc(metrics[0]?.unit||'')}"></label><label>Page<input type="number" min="1" max="${esc(state.preview?.page_count||1)}" value="1" data-manual-page></label><label>Date du prélèvement<input type="date" data-manual-date ${importRowDate('',commonDay)} required></label><button type="button" class="btn outline" data-manual-remove>Retirer cette ligne</button></div>`;}
function importRowDate(rowDay, commonDay){
 const day=rowDay||commonDay||'';
 const inherited=day&&day===commonDay;
 return `value="${esc(day)}"${inherited?` data-common-date="${esc(day)}"`:''}`;
}
function previewRender(p){
 const commonDay=p.document_date||p.sample_date_evidence?.date||'';
 const table=(p.candidates||[]).map((m,i)=>`<tr><td><input type="checkbox" data-candidate="${i}" checked></td><td>${esc(m.label)}<span class="meta">Page ${esc(m.page)} · à vérifier</span></td><td><input aria-label="Valeur" type="number" step="any" data-val="${i}" value="${esc(m.value)}" style="width:92px"></td><td><input aria-label="Unité" data-unit="${i}" value="${esc(m.unit)}" style="width:73px"></td><td><input aria-label="Date" type="date" data-date="${i}" ${importRowDate(m.measured_at,commonDay)}></td></tr>`).join('');
 const findings=(p.findings||[]).map((f,i)=>`<tr><td><input type="checkbox" data-finding="${i}" checked></td><td>${esc(f.label)}<span class="meta">Page ${esc(f.page)} · résultat du document</span></td><td><b>${esc(f.value)}</b></td><td>${esc(f.unit)}</td><td><input aria-label="Date du résultat" type="date" data-finding-date="${i}" ${importRowDate(f.measured_at,commonDay)}></td></tr>`).join('');
 const meds=(p.medications||[]).map((m,i)=>`<tr><td><input type="checkbox" data-med="${i}" checked></td><td>${esc(m.name)} ${esc(m.strength)}</td><td colspan="2">${esc(m.directions)}</td><td><input type="date" data-meddate="${i}" ${importRowDate(m.document_date,commonDay)}></td></tr>`).join('');
 return `<h3>Lecture du document · ${esc(p.page_count)} page(s)</h3><p class="small">${p.candidates.length+(p.findings||[]).length} résultats structurés · ${(p.conclusions||[]).length} conclusion(s) du laboratoire · ${p.page_count} pages à vérifier · ${p.medications.length} ligne(s) de traitement. Vérifiez les résultats, la date et les pages avant de les enregistrer ; la lecture n’est jamais un diagnostic.</p>${ajImportDatePanel(p,commonDay)}${ajImportConclusions(p)}${(p.warnings||[]).filter(w=>!p.sample_date_evidence||!w.includes('Date de prélèvement/mesure')).map(w=>`<div class="warning-box" ${w.includes("Date de prélèvement/mesure")?"data-date-warning":""}>${esc(w)}</div>`).join('')}<div class="table-scroll"><table class="table"><thead><tr><th>Inclure</th><th>Paramètre</th><th>Valeur</th><th>Unité</th><th>Date</th></tr></thead><tbody>${table}${findings}${meds}</tbody></table></div>
 <div class="aj-manual-box"><h4>Un résultat manque ?</h4><p class="small">Saisissez uniquement ce que vous pouvez lire sur votre document. Ajour conservera le lien avec son empreinte et marquera la valeur « saisie par l’utilisateur ».</p><div id="ajManualLines"></div><button type="button" id="ajAddManual" class="btn outline">＋ Ajouter une mesure manuellement</button><label id="ajManualAckWrap" class="perm hidden"><input type="checkbox" id="ajManualAck"> J’ai vérifié chaque valeur manuelle dans le document original.</label></div>
 ${ajImportPages(p)}<div class="form-actions"><button class="btn primary" id="confirmDocument">Confirmer et intégrer les données vérifiées</button></div>`;
}
async function uploadDocument(form){try{const data=new FormData(form);data.set('patient_id',pid());data.set('synthetic_ack','true');const p=await api('/documents/preview',{method:'POST',body:data});state.preview=p;$('previewSpace').innerHTML=previewRender(p);toast((p.candidates.length+(p.findings||[]).length)?`${p.candidates.length+(p.findings||[]).length} résultat(s) détecté(s). Vérifiez les lignes et dates.`:'Aucune valeur détectée automatiquement : consultez le texte lu et saisissez les mesures manuellement.')}catch(err){toast(err.message,true)}}
async function confirmDocument(){const p=state.preview;if(!p)return;try{
 const commonDay=document.querySelector('#ajImportDate')?.value||'';
 const retained_pages=[...document.querySelectorAll('[data-retain-page]:checked')].map(x=>Number(x.dataset.retainPage));
 const transcription_verified=document.querySelector('#ajTranscriptAck')?.checked===true;
 if(retained_pages.length&&!transcription_verified)throw Error('Vérifiez les transcriptions puis cochez la confirmation de lecture.');
 const candidates=(p.candidates||[]).flatMap((m,i)=>{if(!document.querySelector(`[data-candidate="${i}"]`)?.checked)return [];const v=document.querySelector(`[data-val="${i}"]`),d=document.querySelector(`[data-date="${i}"]`);if(v.value===''||!(d.value||commonDay))throw Error('Une valeur sélectionnée est incomplète : indiquez la valeur et la date de prélèvement.');return [{code:m.code,label:m.label,value:Number(v.value),unit:document.querySelector(`[data-unit="${i}"]`).value,measured_at:new Date((d.value||commonDay)+'T12:00:00').toISOString(),page:m.page,original_value:m.original_value,original_unit:m.original_unit,context:m.context||''}];});
 const manual=[...document.querySelectorAll('.aj-manual-line')];if(manual.length&&!document.querySelector('#ajManualAck')?.checked)throw Error('Confirmez la vérification manuelle des valeurs dans le document.');
 for(const line of manual){const code=line.querySelector('[data-manual-code]').value,raw=line.querySelector('[data-manual-value]').value,unit=line.querySelector('[data-manual-unit]').value,day=line.querySelector('[data-manual-date]').value; if(raw===''||!day)throw Error('Chaque mesure manuelle doit avoir une valeur et une date vérifiées.');const item={code,label:line.querySelector('[data-manual-code]').selectedOptions[0].textContent,value:Number(raw),unit,measured_at:new Date(day+'T12:00:00').toISOString(),page:Number(line.querySelector('[data-manual-page]').value),original_value:raw,original_unit:unit,context:'Saisie manuelle utilisateur à partir du document joint',manual:true};candidates.push(item);}
 const medications=(p.medications||[]).flatMap((m,i)=>!document.querySelector(`[data-med="${i}"]`)?.checked?[]:[{name:m.name,strength:m.strength,directions:m.directions,page:m.page,since:document.querySelector(`[data-meddate="${i}"]`).value}]);if(!retained_pages.length&&!candidates.length&&!medications.length&&!(p.findings||[]).some((f,i)=>document.querySelector(`[data-finding="${i}"]`)?.checked))throw Error('Aucune valeur ou prescription sélectionnée. Ajoutez une ligne manuelle ou choisissez une valeur reconnue.');
 const findings=(p.findings||[]).flatMap((f,i)=>{if(!document.querySelector(`[data-finding="${i}"]`)?.checked)return [];const day=document.querySelector(`[data-finding-date="${i}"]`).value||commonDay;if(!day)throw Error('Vérifiez la date de chaque résultat sélectionné.');return [{...f,measured_at:new Date(day+'T12:00:00').toISOString()}];});
 await send('/documents/confirm',{import_token:p.import_token,patient_id:pid(),confirm_patient_identity:true,manual_verified:manual.length>0&&document.querySelector('#ajManualAck')?.checked===true,candidates,medications,findings,document_date:commonDay||null,retained_pages,transcription_verified});closeModal();toast('Résultats et transcriptions sélectionnés enregistrés avec leur provenance.');await refresh();
 }catch(err){toast(err.message,true)}}
async function runForm(form){const name=form.id;const fd=new FormData(form);try{if(name==='patientIdentityForm'){await api(`/patients/${pid()}/identity`,{method:'PUT',body:JSON.stringify(Object.fromEntries(['birth_date','address','profession','insurer','member_test_id','social_test_id','phone','entry_code'].map(k=>[k,fd.get(k)||''])))});toast('Profil d’essai enregistré.');await refresh();return}else if(name==='registerForm'){const u=await send('/demo/accounts',{role:fd.get('role'),name:fd.get('name'),synthetic_ack:true,...Object.fromEntries(['birth_date','address','profession','insurer','member_test_id','social_test_id'].map(k=>[k,fd.get('role')==='patient'?(fd.get(k)||''):'']))});state.selectedEmail=u.email;closeModal();await showLogin();$('loginError').textContent='Compte fictif créé. Cliquez sur « Entrer dans Ajour ». Les accès professionnels doivent être accordés depuis le compte patient.';return}else if(name==='inviteForm'){await send(`/patients/${pid()}/grants`,{user_id:fd.get('user_id'),permissions:['glucose','vitals','meds','messages'],revoked:false});toast('Le nouveau compte dispose désormais des accès fictifs autorisés.');await refresh();return}else if(name==='measureForm'){const unit=fd.get('unit'),measured=fd.get('measured_at');await send(`/patients/${pid()}/measures`,{code:fd.get('code'),value:Number(fd.get('value')),unit,measured_at:new Date(measured).toISOString(),context:fd.get('context')||''});toast('Mesure fictive transmise. Les courbes autorisées sont actualisées.')}else if(name==='rxForm'){await send(`/patients/${pid()}/prescriptions`,{name:fd.get('name'),schedule:fd.get('schedule')});toast('Prescription fictive visible dans les espaces autorisés.')}else if(name==='noteForm'){await send(`/patients/${pid()}/notes`,{kind:fd.get('kind'),body:fd.get('body')});toast('Note transmise au suivi médical autorisé.')}else if(name==='messageForm'){await send(`/patients/${pid()}/messages`,{recipient_id:fd.get('recipient_id'),body:fd.get('body')});toast('Message déposé dans la boîte du destinataire.')}else if(name==='taskForm'){await send(`/patients/${pid()}/tasks`,{assignee_id:fd.get('assignee_id'),title:fd.get('title'),due_date:fd.get('due_date')});toast('Consigne transmise à l’infirmière fictive.')}else if(name==='uploadForm'){await uploadDocument(form);return}else if(name==='vaccineForm'){await send(`/patients/${pid()}/vaccinations`,{name:fd.get('name'),administered_on:fd.get('administered_on')||null,source:fd.get('source'),status:fd.get('status')});toast('Vaccin déclaré : la vérification reste nécessaire.')}else if(name==='preventionForm'){await send(`/patients/${pid()}/prevention`,{key:fd.get('key'),status:fd.get('status'),note:fd.get('note')||''});toast('Statut de prévention mis à jour.')}else if(name==='wellbeingForm'){await send(`/patients/${pid()}/wellbeing`,{category:fd.get('category'),note:fd.get('note'),recorded_on:fd.get('recorded_on')});toast('Note personnelle enregistrée.')}else if(name==='slotForm'){await send('/appointments/slots',{starts_at:new Date(fd.get('starts_at')).toISOString(),duration:Number(fd.get('duration')),location:fd.get('location')});toast('Créneau proposé dans Ajour.')}else if(name==='bookForm'){await send('/appointments',{slot_id:fd.get('slot_id'),reason:fd.get('reason'),scopes:fd.getAll('share')});toast('Rendez-vous fictif réservé ; le partage choisi est limité dans le temps.')} else if(form.dataset.grant){await send(`/patients/${pid()}/grants`,{user_id:form.dataset.grant,permissions:fd.getAll('permission'),revoked:!!fd.get('revoked')});toast('Droits familiaux mis à jour.');await refresh();return}await refresh();}catch(err){toast(err.message,true)}}
async function dispense(medId){const quantity=prompt('Quantité fictivement délivrée :','1 boîte');if(quantity===null)return;try{await send(`/patients/${pid()}/dispenses`,{medication_id:medId,quantity,note:'Délivrance de démonstration'});toast('Délivrance fictive enregistrée.');await refresh()}catch(err){toast(err.message,true)}}
async function complete(tid){try{await api(`/patients/${pid()}/tasks/${encodeURIComponent(tid)}/complete`,{method:'POST'});toast('Consigne marquée réalisée (simulation).');await refresh()}catch(err){toast(err.message,true)}}

/* v0.4: simple language, with source information; never a clinical interpretation. */
async function loadExperience(){
  if(!state.user||!pid())return;
  const extra={};
  const tasks=[['story',`/patients/${pid()}/story`]];
  if(scope('vaccines'))tasks.push(['vaccines',`/patients/${pid()}/vaccinations`]);
  if(scope('prevention'))tasks.push(['prevention',`/patients/${pid()}/prevention`]);
  if(scope('wellbeing')&&['patient','family'].includes(state.user.role))tasks.push(['wellbeing',`/patients/${pid()}/wellbeing`]);
  if(['patient','family'].includes(state.user.role))tasks.push(['professions','/catalog/professions']);
  if(['patient','family','doctor','nurse'].includes(state.user.role)&&['glucose','vitals','labs'].some(scope))tasks.push(['healthmap',`/patients/${pid()}/health-map`]);
  if(state.user.role==='patient'||['doctor','dentist','nurse','optician','radiologist','podiatrist','orthotist'].includes(state.user.role)||scope('appointments')){
    tasks.push(['appointments',`/appointments${['doctor','dentist','nurse','optician','radiologist','podiatrist','orthotist'].includes(state.user.role)?'':`?patient_id=${encodeURIComponent(pid())}`}`]);
    tasks.push(['slots','/appointments/slots']);
  }
  await Promise.all(tasks.map(async ([key,url])=>{try{extra[key]=await api(url)}catch{extra[key]=null}}));
  state.extra=extra;
}
async function loadMedicalCatalog(){
 try{state.catalog=await api('/catalog/health-indicators');
   if(state.user.role==='doctor')state.specialty=await api('/preferences/specialty');
 }catch(e){console.warn('Catalogue Ajour non disponible',e.message)}
}
function doctorSpecialtyIntro(){
 if(!state.specialty)return '';
 const focus=state.specialty.profile?.priority||[];
 return `<section class="clarity-hero"><div><div class="eyebrow">VUE MÉDICALE ORGANISÉE PAR MÉTIER</div><h2>${esc(state.specialty.specialty)}</h2><p>${focus.length} rubriques prioritaires dans le catalogue. Cette sélection ne change jamais les autorisations d’accès.</p><button class="btn outline" data-tab="healthmap">Ouvrir le tableau spécialisé →</button></div></section>`;
}
function healthMapPage(){
 const map=state.extra.healthmap;
 if(!map)return panel('Mon carnet de santé','<div class="empty">Aucun catalogue autorisé pour ce profil.</div>');
 const doctor=state.user.role==='doctor';
 const choices=state.catalog?.specialties||[];
 const selector=doctor?`<div class="specialty-select"><label for="specialtyChooser">Exercice principal</label><select class="select" id="specialtyChooser">${choices.map(v=>`<option value="${esc(v)}" ${state.specialty?.specialty===v?'selected':''}>${esc(v)}</option>`).join('')}</select><label for="secondarySpecialtyChooser">Autre spécialité (facultative)</label><select class="select" id="secondarySpecialtyChooser"><option value="">Aucune</option>${choices.map(v=>`<option value="${esc(v)}" ${state.specialty?.secondary_specialty===v?'selected':''}>${esc(v)}</option>`).join('')}</select><p class="small">Les rubriques prioritaires des deux spécialités sont combinées ; aucun droit d’accès supplémentaire.</p></div>`:'';
 const groups=[...new Set((map.items||[]).map(x=>x.domain))].sort((a,b)=>a.localeCompare(b,'fr'));
 const filtered=(map.items||[]).filter(x=>(state.domainFilter==='all'||x.domain===state.domainFilter)&&(!state.showOnlyMeasured||x.status!=='not_recorded'));
 const found=filtered.filter(x=>x.status!=='not_recorded');
 const notice='<div class="warning-box">« Non renseigné » signifie simplement qu’aucune donnée accessible n’a été enregistrée. Cela ne veut jamais dire « examen à faire ». Aucune interprétation ou alerte médicale automatique.</div>';
 const cards=filtered.map(x=>`<article class="indicator-card ${x.status!=='not_recorded'?'is-known':''}"><div class="indicator-top"><span class="indicator-domain">${esc(x.domain)}</span><span class="indicator-state">${x.status==='measured'?'Mesure enregistrée':x.status==='documented'?'Information documentée':'Non renseigné'}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.explanation)}</p>${x.latest?`<div class="indicator-reading">${fmt(x.latest.value)} <small>${esc(x.latest.unit)}</small></div><div class="small">${date(x.latest.measured_at)} · ${esc(statusText(x.latest.status))}${x.latest.context?' · '+esc(x.latest.context):''}</div><button class="pill-button" data-source="${esc(x.latest.source_id)}">Voir la source ↗</button> ${x.type==='number'?`<button class="pill-button" data-chart="${esc(x.code)}">Voir la courbe</button>`:''}`:`<div class="indicator-unknown">${x.summary?esc(x.summary):'Aucune information disponible ici pour le moment.'}</div>`}</article>`).join('');
 return `<div class="stack">${panel(doctor?'Dossier clinique par spécialité':'Ma santé, domaine par domaine',`<div class="healthmap-head"><div><h3>${doctor?'Afficher les informations utiles à cette consultation':'Comprendre toute mon histoire médicale'}</h3><p>Une même histoire, expliquée simplement. Les données sont conservées avec leur date, leur source et leur niveau de vérification.</p></div></div>${selector}${doctor&&map.specialty?.workflow?.length?`<div class="workflow-list"><b>Points du parcours à documenter</b>${map.specialty.workflow.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}<div class="indicator-filters"><label>Explorer un domaine<select id="domainFilter" class="select"><option value="all">Tous les domaines</option>${groups.map(g=>`<option value="${esc(g)}" ${state.domainFilter===g?'selected':''}>${esc(g)}</option>`).join('')}</select></label><label class="perm"><input type="checkbox" id="showMeasured" ${state.showOnlyMeasured?'checked':''}> Seulement les données renseignées</label></div><p class="small">${filtered.length} rubrique(s) affichée(s), dont ${found.length} avec des informations.</p>${notice}`)}<section class="indicator-grid">${cards||'<div class="empty">Aucune rubrique pour ces filtres.</div>'}</section>${panel('Ce que Ajour ne sait pas encore',`<p>Les rubriques sans valeur peuvent avoir été examinées ailleurs, sans être enregistrées ici. Les résultats non numériques, comme une IRM ou un compte rendu opératoire, nécessiteront des modules documentaires structurés supplémentaires.</p><p>Le catalogue s’enrichit sans obliger les patients à passer de nouveaux examens.</p>`)}</div>`;
}
function storyIntro(){const st=state.extra.story;if(!st)return '';
  return `<section class="clarity-hero"><span class="clarity-mark">✧</span><div><div class="eyebrow">LA SANTÉ EXPLIQUÉE SIMPLEMENT</div><h2>Mon histoire de santé, en clair</h2><p>« ${esc(st.summary)} »</p><small>${esc(st.intro)}</small></div><button class="btn outline" data-tab="story">Comprendre mes résultats →</button></section>`;
}
function statusText(status){return ({synthetic_verified:'Résultat fictif',patient_confirmed:'Relu par un utilisateur',professional_verified:'Saisi par un professionnel fictif',lab_submitted_demo:'Transmis par laboratoire (test)',declare:'Déclaré, non vérifié',incertain:'Information incertaine'})[status]||'À vérifier'}
function storyPage(){const st=state.extra.story;
 if(!st)return panel('Ma santé en clair','<div class="empty">Aucun résultat accessible à expliquer pour ce dossier.</div>');
 return `<div class="story-header"><span class="eyebrow">COMPRENDRE SANS JARGON</span><h2>${esc(st.title)}</h2><p>${esc(st.intro)}</p><div class="story-count">${esc(st.summary)}</div></div>
 <div class="story-grid">${(st.cards||[]).map(v=>`<article class="story-card"><div class="eyebrow">${esc(v.title)}</div><div class="story-value">${fmt(v.value)} <small>${esc(v.unit)}</small></div><p>${esc(v.explanation)}</p><div class="story-source">${esc(v.sentence)}<br><b>${esc(statusText(v.status))}</b>${v.context?` · ${esc(v.context)}`:''}</div><button class="pill-button" data-source="${esc(v.source_id)}">D’où vient cette valeur ? ↗</button><button class="pill-button" data-tab="analyses">Voir la courbe</button></article>`).join('')||'<div class="empty">Ajoutez une analyse pour alimenter cette courbe.</div>'}</div>
 <div class="warning-box">${esc(st.disclaimer)} Si vous avez une question sur votre santé, discutez-en avec un professionnel.</div>`;
}
function vaccinesPage(){const list=state.extra.vaccines||[];
const form=state.user.role==='patient'?`<form class="simple-form" id="vaccineForm"><h3>Ajouter un vaccin fictif</h3><div class="form-field"><label>Nom du vaccin</label><input name="name" minlength="2" maxlength="120" required placeholder="Ex. Vaccin fictif A"></div><div class="form-field"><label>Date (facultative)</label><input type="date" name="administered_on"></div><div class="form-field"><label>Source déclarée</label><input name="source" maxlength="160" value="Carnet de vaccination fictif"></div><div class="form-field"><label>Fiabilité</label><select name="status" class="select"><option value="declare">Je le déclare (non vérifié)</option><option value="incertain">Je ne suis pas certain(e)</option></select></div><button class="btn primary">Enregistrer cette information</button></form>`:'';
return `<div class="stack">${panel('Mon carnet de vaccination',`<p>Vous pouvez retrouver les vaccins que vous avez ajoutés et leur date, même si celle-ci reste inconnue.</p><div class="warning-box">Absence de vaccin dans Ajour ne signifie pas qu’il n’a jamais été réalisé. Les rappels doivent être vérifiés auprès d’un professionnel.</div>${list.map(v=>row(v.name,`Date : ${v.administered_on?date(v.administered_on):'inconnue'} · ${statusText(v.status)}`,esc(v.source),'✹')).join('')||'<div class="empty">Aucun vaccin déclaré dans cette simulation.</div>'}`)}${form?panel('Ajouter à mon carnet',form):''}</div>`;
}
function preventionPage(){const list=state.extra.prevention||[];
 return `<div class="stack">${panel('Ma prévention, sans inquiétude inutile',`<p>Des sujets utiles à aborder avec votre médecin. <b>Ce ne sont ni des examens obligatoires ni des rendez-vous prescrits.</b></p><div class="prevention-list">${list.map(x=>`<article class="prevention-card"><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><small>Mon suivi : <b>${esc(({'inconnu':'Je ne sais pas','a_discuter':'À discuter','programme':'Programmé','realise':'Déjà réalisé','non_concerne':'Non concerné'})[x.status]||x.status)}</b></small><div class="small"><a href="${esc(x.reference)}" target="_blank" rel="noopener noreferrer">Voir la source officielle ↗</a></div>${state.user.role==='patient'?`<form id="preventionForm" class="prevention-edit"><input type="hidden" name="key" value="${esc(x.key)}"><select class="select" name="status"><option value="inconnu">Je ne sais pas</option><option value="a_discuter">À discuter</option><option value="programme">Programmé</option><option value="realise">Déjà réalisé</option><option value="non_concerne">Non concerné</option></select><input name="note" placeholder="Note personnelle (facultative)" maxlength="180"><button class="btn outline">Mettre à jour</button></form>`:''}</article>`).join('')}</div>`,'Repères généraux tirés de sources publiques et datées, non adaptés automatiquement à votre cas.')}</div>`;
}
function wellbeingPage(){const list=state.extra.wellbeing||[];
const form=state.user.role==='patient'?`<form id="wellbeingForm" class="simple-form"><h3>Écrire quelques mots sur ma journée</h3><p>Pas besoin de note sur 10. Vous choisissez ce que vous souhaitez garder en mémoire.</p><div class="form-field"><label>Le sujet</label><select name="category" class="select"><option value="sommeil">Sommeil</option><option value="activite">Activité</option><option value="humeur">Humeur</option><option value="douleur">Ressenti physique</option><option value="energie">Énergie</option><option value="autre">Autre</option></select></div><div class="form-field"><label>Date</label><input type="date" name="recorded_on" value="${new Date().toISOString().slice(0,10)}" required></div><div class="form-field"><label>Ce que je veux retenir</label><textarea name="note" maxlength="600" minlength="2" required placeholder="Ex. J'ai mieux dormi cette nuit."></textarea></div><button class="btn primary">Garder ce souvenir</button></form>`:'';
return `<div class="stack">${panel('Mon bien-être',`<p>Un journal facultatif pour garder une trace de ce que vous ressentez. Vous n’êtes pas obligé(e) de tout partager.</p>${list.map(x=>row(x.category,date(x.recorded_on),esc(x.note),'♡')).join('')||'<div class="empty">Votre journal fictif est vide.</div>'}`)}${form?panel('Ajouter une note personnelle',form):''}</div>`;
}
function professionsPage(){return `<section class="aj-practice-strip"><h2>À qui m'adresser ?</h2><p>Décrivez en quelques mots votre besoin. Ajour propose des spécialités à rechercher, sans poser de diagnostic ni évaluer l'urgence.</p><form id="practiceOrient"><label>Que cherchez-vous ?<textarea name="symptom" maxlength="350" rows="3" required placeholder="Ex. Je vois flou, j'ai des vertiges..."></textarea></label><button class="btn primary">Chercher un professionnel</button></form><div id="practiceOrientResult" role="status" aria-live="polite"></div><p class="small">En cas de douleur intense, perte brutale de vision, faiblesse d'un côté, malaise important ou autre urgence : appelez le 15 ou le 112. Ce module n'assure pas de triage médical.</p></section>`}

function appointmentsPage(){const role=state.user.role;const appts=state.extra.appointments||[];const slots=state.extra.slots||[];
const shareLabels={glucose:'Glycémie',vitals:'Tension et constantes',labs:'Bilans biologiques',meds:'Médicaments'};
const bookings=role==='patient'?panel('Prendre rendez-vous',`<p>Le praticien verra seulement ce que vous décidez de préparer, pendant une période limitée. Aucun partage n’est précoché.</p>${slots.length?`<form class="simple-form" id="bookForm"><div class="form-field"><label>Choisir un créneau</label><select name="slot_id" class="select">${slots.map(x=>`<option value="${esc(x.id)}">${esc(x.provider)} — ${esc(clock(x.starts_at))} · ${esc(x.location)}</option>`).join('')}</select></div><div class="form-field"><label>Motif en quelques mots</label><input name="reason" maxlength="180" value="Consultation de suivi"></div><fieldset class="sharing-options"><legend>Ce que j'autorise à préparer</legend>${Object.entries(shareLabels).map(([key,v])=>`<label><input type="checkbox" name="share" value="${key}"> ${v}</label>`).join('')}</fieldset><button class="btn primary">Réserver mon créneau</button></form>`:'<div class="empty">Aucun créneau proposé. Connectez-vous comme médecin et ajoutez-en un.</div>'}`):'';
const doctorForm=['doctor','dentist','nurse','optician','radiologist','podiatrist','orthotist'].includes(role)?panel('Proposer un créneau',`<form id="slotForm" class="simple-form"><div class="form-field"><label>Date et heure</label><input type="datetime-local" name="starts_at" required min="${localNow()}"></div><div class="form-field"><label>Durée</label><select class="select" name="duration"><option value="30">30 minutes</option><option value="20">20 minutes</option><option value="45">45 minutes</option><option value="60">60 minutes</option></select></div><div class="form-field"><label>Lieu fictif</label><input name="location" maxlength="100" value="Cabinet"></div><button class="btn primary">Publier le créneau</button></form>`):'';
 const upcoming=panel('Mes rendez-vous',appts.map(x=>`<div class="row-item"><span class="row-symbol">▣</span><span class="row-info"><strong>${esc(clock(x.starts_at))} — ${role!=='patient'?esc(x.patient_name):esc(x.provider)}</strong><small>${esc(x.location)} · ${x.status==='booked'?'Réservé':'Annulé'} · ${x.scope?.length?x.scope.map(k=>shareLabels[k]).join(', '):'Aucun dossier partagé'}</small>${role!=='patient'?`<small>Motif : ${esc(x.reason)}</small>`:''}</span><span class="row-end">${x.status==='booked'?(role==='doctor'?`<button class="pill-button" data-brief="${esc(x.id)}">Préparation autorisée</button>`:'')+` <button class="pill-button" data-cancel-appt="${esc(x.id)}">Annuler</button>`:''}</span></div>`).join('')||'<div class="empty">Aucun rendez-vous fictif enregistré.</div>','Une annulation coupe immédiatement l’accès lié à ce rendez-vous.');
 return `<div class="stack">${bookings}${doctorForm}${upcoming}</div>`;
}
async function cancelAppointment(id){if(!confirm('Annuler ce rendez-vous fictif ?'))return;try{await api(`/appointments/${encodeURIComponent(id)}/cancel`,{method:'POST'});toast('Rendez-vous annulé et partage associé révoqué.');await refresh()}catch(e){toast(e.message,true)}}
async function showBrief(id){try{const x=await api(`/appointments/${encodeURIComponent(id)}/brief`);showModal(`<div class="eyebrow">DOSSIER PRÉ-CONSULTATION FICTIF</div><h2>${esc(x.patient)}</h2><p>Rendez-vous : ${esc(date(x.starts_at))}</p><p>Motif déclaré : ${esc(x.motif)}</p><h3>Données expressément partagées</h3><p>${esc(x.shared_categories.join(', ')||'Aucune')}</p>${(x.observations||[]).slice(-15).map(o=>row(o.label,date(o.measured_at),`${fmt(o.value)} ${esc(o.unit)}`)).join('')}<h3>Médicaments partagés</h3>${(x.medications||[]).map(m=>row(m.name,m.schedule)).join('')}<div class="warning-box">${esc(x.disclaimer)}</div>`)}catch(e){toast(e.message,true)}}
function bind(){document.addEventListener('click',async event=>{const b=event.target.closest('button,circle[data-source]');if(!b)return;if(b.dataset.importDateChoice){const input=$('ajImportDate');input.value=b.dataset.importDateChoice;ajApplyImportDate(input.value);return}if(b.id==='ajAddManual'){$('ajManualLines').insertAdjacentHTML('beforeend',ajManualLine());$('ajManualAckWrap').classList.remove('hidden');return}if(b.hasAttribute('data-manual-remove')){b.closest('.aj-manual-line')?.remove();if(!document.querySelector('.aj-manual-line'))$('ajManualAckWrap')?.classList.add('hidden');return}if(b.hasAttribute('data-home')){ajHome();return}if(b.hasAttribute('data-nav-back')){ajBack();return}if(b.dataset.historyIndex!==undefined){const ix=Number(b.dataset.historyIndex);if(Number.isInteger(ix)&&ix>=0&&ix<state.tabHistory.length){const path=state.tabHistory.slice(0,ix+1);state.tab=path.pop();state.tabHistory=path;await refresh();}return}if(b.dataset.cancelAppt){await cancelAppointment(b.dataset.cancelAppt);return}if(b.dataset.brief){await showBrief(b.dataset.brief);return}if(b.dataset.account){state.selectedEmail=b.dataset.account;await showLogin();return}if(b.dataset.jump){const [target,anchor]=b.dataset.jump.split(':');if(!tabs().some(x=>x[0]===target))return;ajNavigate(target);await loadExperience();if(target==='journeys')await loadJourneyData();await loadCareData();render();$('sidebar').classList.remove('open');requestAnimationFrame(()=>{const el=document.getElementById(anchor);if(el){el.open=true;el.scrollIntoView({behavior:'smooth',block:'start'});el.querySelector('input:not([type=checkbox])')?.focus({preventScroll:true})}});return}if(b.dataset.tab){ajNavigate(b.dataset.tab);await loadExperience();if(state.tab==='journeys')await loadJourneyData();await loadCareData();render();$('sidebar').classList.remove('open');return}if(b.dataset.patient){state.patient=state.patients.find(p=>p.id===b.dataset.patient);state.tabHistory=[];state.tab=['optician','radiologist','dentist','podiatrist','orthotist'].includes(state.user.role)?'careflows':'dashboard';state.metric='glucose';state.extra={};state.patientSearch='';await refresh();$('sidebar').classList.remove('open');return}if(b.dataset.source){await showSource(b.dataset.source);return}if(b.dataset.chart){state.metric=b.dataset.chart;ajNavigate('analyses');await loadExperience();render();return}if(b.dataset.dispense){await dispense(b.dataset.dispense);return}if(b.dataset.complete){await complete(b.dataset.complete);return}if(b.id==='openImport'){showImport();return}if(b.id==='confirmDocument'){await confirmDocument();return}if(b.id==='manualRefresh'){await refresh();return}});document.addEventListener('submit',e=>{e.preventDefault();runForm(e.target)});document.addEventListener('input',e=>{if(e.target.id==='patientSearch'){state.patientSearch=e.target.value;const q=state.patientSearch.toLocaleLowerCase('fr');const box=$('patientPicker').querySelector('.aj-patient-list');if(box)box.querySelectorAll('button[data-patient]').forEach(el=>{el.hidden=!el.textContent.toLocaleLowerCase('fr').includes(q)});}});document.addEventListener('change',async e=>{if(e.target.id==='ajImportDate'){ajApplyImportDate(e.target.value);return}if(e.target.matches('[data-date], [data-finding-date], [data-meddate], [data-manual-date]')){delete e.target.dataset.commonDate;return}if(e.target.hasAttribute('data-manual-code')){const unit=e.target.closest('.aj-manual-line').querySelector('[data-manual-unit]');unit.value=e.target.selectedOptions[0]?.dataset.unit||'';return}if(e.target.id==='registerRole'){$('registerPatientFields')?.classList.toggle('hidden',e.target.value!=='patient');return}if(e.target.id==='metricChooser'||e.target.id==='analysisMetricChooser'){state.metric=e.target.value;render()}else if(e.target.id==='periodChooser'){state.period=e.target.value;render()}else if(e.target.id==='domainFilter'){state.domainFilter=e.target.value;render()}else if(e.target.id==='showMeasured'){state.showOnlyMeasured=e.target.checked;render()}else if(['specialtyChooser','secondarySpecialtyChooser'].includes(e.target.id)){const value=$('specialtyChooser')?.value,additional=$('secondarySpecialtyChooser')?.value||null;try{state.specialty=await send('/preferences/specialty',{specialty:value,secondary_specialty:additional});state.extra.healthmap=await api(`/patients/${pid()}/health-map`);toast('Vue spécialisée mise à jour, sans changement d’accès.');render()}catch(err){toast(err.message,true)}}else if(e.target.id==='measureCode'){const opt=e.target.selectedOptions[0];const input=$('measureUnit');if(input)input.value=opt?.dataset.unit||''}});$('loginBtn').addEventListener('click',doLogin);$('registerBtn').addEventListener('click',showRegister);$('comfortBtn').addEventListener('click',()=>document.documentElement.classList.toggle('comfort'));$('password').addEventListener('keydown',e=>{if(e.key==='Enter')doLogin()});$('logoutBtn').addEventListener('click',logout);$('closeModal').addEventListener('click',closeModal);$('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});$('menuBtn').addEventListener('click',()=>$('sidebar').classList.toggle('open'));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()})}
window.addEventListener('DOMContentLoaded',()=>{bind();start();setInterval(async()=>{if(state.user&&pid()&&$('modal').classList.contains('hidden')&&!['team','documents'].includes(state.tab)){try{state.data=await api(`/patients/${pid()}/overview`);if(['story','healthmap'].includes(state.tab))await loadExperience();if(['dashboard','analyses','story','healthmap','medications','messages','notes','tasks','journeys'].includes(state.tab)){await loadJourneyData();await loadCareData();await practiceReload();render();}}catch{}}},8000)});

function ajFindingsPanel(){const fs=state.data.findings||[];if(!fs.length)return '';return panel('Résultats de laboratoire importés',`<div class="table-scroll"><table class="table"><thead><tr><th>Date</th><th>Examen</th><th>Résultat</th><th>Source</th></tr></thead><tbody>${fs.map(f=>`<tr><td>${date(f.measured_at)}</td><td>${esc(f.label)}</td><td><b>${esc(f.value)} ${esc(f.unit)}</b><span class="meta">Confirmé par l’utilisateur</span></td><td>Page ${esc(f.page)} <button class="pill-button" data-source="${esc(f.source_id)}">Voir provenance ↗</button></td></tr>`).join('')}</tbody></table></div>`,'Résultats littéraux et valeurs bornées conservés sans conversion en points de courbe.');}

function ajImportDatePanel(p,commonDay){
 const choices=p.sample_date_options||[];
 const alternatives=choices.length>1?`<p class="small">Sélectionnez la date indiquée sur le document.</p>
 <div class="aj-import-date-options">${choices.map(day=>`<button type="button" class="btn outline" data-import-date-choice="${esc(day)}">${esc(day.split('-').reverse().join('/'))}</button>`).join('')}</div>`:'';
 const evidence=p.sample_date_evidence;
 const review=evidence?`<p class="small aj-date-evidence">Date lue sur la page ${esc(evidence.page)} : « ${esc(evidence.excerpt)} ». Vérifiez-la avant l’enregistrement.</p>
 <details class="aj-date-evidence"><summary>Autres dates présentes dans le texte du PDF</summary>${alternatives}</details>`:alternatives;
 return `<div class="aj-manual-box"><h4>Date du prélèvement</h4><label>Date commune
 <input id="ajImportDate" aria-label="Date commune du prélèvement" type="date" value="${esc(commonDay)}"></label>
 ${review}</div>`;
}
function ajApplyImportDate(day){document.querySelectorAll('[data-date-warning]').forEach(el=>{el.hidden=!!day;});document.querySelectorAll('[data-date], [data-finding-date], [data-meddate], [data-manual-date]').forEach(input=>{if(!input.value||input.dataset.commonDate===input.value){input.value=day;input.dataset.commonDate=day;}});}
function ajImportConclusions(p){return (p.conclusions||[]).length?`<div class="aj-manual-box"><h4>Conclusions écrites par le laboratoire</h4>${p.conclusions.map(c=>`<p><b>Page ${esc(c.page)}</b> : ${esc(c.text)}</p>`).join('')}<p class="small">Texte du laboratoire, sans interprétation ajoutée. Le contexte complet se trouve dans les transcriptions ci-dessous.</p></div>`:'';}
function ajImportPages(p){return `<div class="aj-manual-box"><h4>Vérification et conservation des ${esc(p.page_count)} pages</h4><p class="small">Les résultats structurés ne couvrent pas tout le texte. Conservez les transcriptions vérifiées pour retrouver aussi les conclusions, conseils, antécédents, seuils et informations non classées. Une transcription peut comporter des erreurs ; comparez-la à l’original. Le PDF et les images d’origine ne sont pas conservés.</p>${(p.text_previews||[]).map((text,i)=>{const count=(p.candidates||[]).filter(x=>x.page===i+1).length+(p.findings||[]).filter(x=>x.page===i+1).length;return `<div><label><input type="checkbox" data-retain-page="${i+1}" ${text.trim()?'checked':'disabled'}> Conserver la transcription de la page ${i+1}</label><details class="aj-ocr-diagnostic"><summary>Page ${i+1} · ${count} résultat(s) structuré(s) · ${text.trim()?'texte à vérifier':'AUCUN TEXTE LU — vérifier l’original'}</summary><pre>${esc(text||'[Page illisible : aucune transcription]')}</pre></details></div>`;}).join('')}<label class="perm"><input id="ajTranscriptAck" type="checkbox"> J’ai comparé les transcriptions sélectionnées au document et confirmé l’identité du patient.</label></div>`;}
function ajDocumentPagesPanel(){const ps=state.data.document_pages||[];if(!ps.length)return '';return panel('Textes des documents importés',ps.map(p=>`<details class="aj-ocr-diagnostic"><summary>Page ${esc(p.page)} · transcription vérifiée par l’utilisateur</summary><pre>${esc(p.text)}</pre><button class="pill-button" data-source="${esc(p.source_id)}">Voir provenance ↗</button></details>`).join(''),'Texte conservé avec sa source, y compris les informations qui ne figurent pas dans les résultats structurés.');}
